"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[597],{2861:e=>{e.exports=JSON.parse('{"functions":[{"name":"RegisterDefinition","desc":"Registers a movement module with input actions, default state fields, and a\\n`Process` function.\\n\\nModules run in priority order (lower runs first). Register before `Start`\\nwhen possible; if already started, active players are updated immediately.\\nDuplicate names are ignored.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"definition","desc":"Module definition to register","lua_type":"ServerAuthToolkitTypes.MovementModuleDefinition"}],"returns":[],"function_type":"static","tags":["Register"],"source":{"line":864,"path":"src/init.luau"}},{"name":"Teleport","desc":"Teleports a player\'s character to a target CFrame with server authority.\\n\\nServer-only. Sets the root part CFrame and replicates the new state so\\npredicting clients roll back to it.\\n\\nThe toolkit does not assume any module-specific state fields. Pass\\n`modifyState` to mutate the player\'s authoritative movement state before it is\\ncaptured to attributes (for example, zeroing a module\'s `Velocity` so the\\ncharacter does not keep its momentum after the move). The callback runs after\\nthe position is resolved and before replication.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"player","desc":"The player whose character to teleport","lua_type":"Player"},{"name":"targetCFrame","desc":"Destination CFrame; position is used, facing is flattened","lua_type":"CFrame"},{"name":"modifyState","desc":"Optional hook to mutate the movement state before replication","lua_type":"((state: MovementState) -> ())?"},{"name":"preserveLookDirection","desc":"When true, keeps the current facing instead of using targetCFrame","lua_type":"boolean?"}],"returns":[{"desc":"True if the teleport was applied","lua_type":"boolean"}],"function_type":"static","tags":["Utility"],"realm":["Server"],"source":{"line":911,"path":"src/init.luau"}},{"name":"RegisterPreCameraSimulation","desc":"Registers a callback that runs on the client before movement simulation each\\nframe.\\n\\nUse for client-only setup that must happen before input is applied. Callbacks\\nrun in registration order. Server calls log a warning and return a no-op\\nunregister function.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"callbackName","desc":"Unique name for this callback","lua_type":"string"},{"name":"callback","desc":"Called each pre-simulation step with deltaTime","lua_type":"ServerAuthToolkitTypes.PreCameraSimulationCallback"}],"returns":[{"desc":"Unregisters the callback","lua_type":"() -> ()"}],"function_type":"static","tags":["Camera"],"realm":["Client"],"source":{"line":980,"path":"src/init.luau"}},{"name":"RegisterPostCameraVisualEffect","desc":"Registers a visual callback that runs on the client after the camera updates.\\n\\nUse for camera shake, FOV changes, or other effects that should not affect\\nmovement simulation. Server calls log a warning and return a no-op unregister\\nfunction.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"callbackName","desc":"Unique name for this callback","lua_type":"string"},{"name":"callback","desc":"Called each render step with deltaTime","lua_type":"ServerAuthToolkitTypes.PostCameraVisualCallback"},{"name":"renderPriorityOffset","desc":"Offset from camera render priority. Defaults to 2","lua_type":"number?"}],"returns":[{"desc":"Unregisters the callback","lua_type":"() -> ()"}],"function_type":"static","tags":["Camera"],"realm":["Client"],"source":{"line":1022,"path":"src/init.luau"}},{"name":"GetStoredSimulationCameraBaseCFrame","desc":"Returns the camera CFrame captured for client movement simulation.\\n\\nThe toolkit stores this after the camera updates so simulation uses a stable\\ncamera state. Returns nil on the server or before a capture exists.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[{"desc":"The stored simulation camera CFrame","lua_type":"CFrame?"}],"function_type":"static","tags":["Camera"],"realm":["Client"],"source":{"line":1064,"path":"src/init.luau"}},{"name":"ResetNeededStates","desc":"Resets a player\'s custom movement state fields to the merged defaults from\\nall registered modules.\\n\\nOnly fields from module `NeededStates` are reset. Built-in fields like\\n`Character` and `RootPart` are not changed.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"playerMovementState","desc":"The movement state to reset","lua_type":"ServerAuthToolkitTypes.MovementState"}],"returns":[],"function_type":"static","tags":["States"],"source":{"line":1082,"path":"src/init.luau"}},{"name":"GetLocalMovementState","desc":"Returns the local player\'s movement state table.\\n\\nThis is the same table updated each simulation step by registered modules.\\nReturns nil on the server.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[{"desc":"The local player\'s movement state","lua_type":"ServerAuthToolkitTypes.MovementState?"}],"function_type":"static","tags":["States"],"realm":["Client"],"source":{"line":1099,"path":"src/init.luau"}},{"name":"RegisterAnimations","desc":"Registers animations for use with the animation API.\\n\\nEach name maps to playback settings used by `PlayAnimation`, `StopAnimation`,\\nand the animation query methods.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animations","desc":"Animation names to settings","lua_type":"{ [string]: ServerAuthToolkitTypes.AnimationSettings }"}],"returns":[],"function_type":"static","tags":["Register"],"source":{"line":1116,"path":"src/init.luau"}},{"name":"PlayAnimation","desc":"Plays a registered animation.\\n\\nThe animation must be registered first with `RegisterAnimations`.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to play","lua_type":"string"},{"name":"speedOverride","desc":"Optional playback speed. Uses registered speed if omitted","lua_type":"number?"}],"returns":[],"function_type":"static","tags":["Animations"],"source":{"line":1134,"path":"src/init.luau"}},{"name":"RestartAnimation","desc":"Restarts a registered one-shot animation from the beginning, even while it\\nis still playing.\\n\\nUse for retriggered actions like gunshots, where each event needs a fresh\\nplaythrough. `PlayAnimation` deliberately keeps an in-flight one-shot going\\nso that replayed simulation steps cannot restart it; RestartAnimation is the\\nexplicit trigger for a new playthrough, so only call it from event-driven\\ncode (input handlers, remotes), never from simulation logic that reruns\\nduring rollback resimulation. Looped animations fall back to `PlayAnimation`\\nbehavior.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to restart","lua_type":"string"},{"name":"speedOverride","desc":"Optional playback speed. Uses registered speed if omitted","lua_type":"number?"}],"returns":[],"function_type":"static","tags":["Animations"],"source":{"line":1154,"path":"src/init.luau"}},{"name":"StopAnimation","desc":"Stops a registered animation.\\n\\nUses the registered stop fade time when blending out.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to stop","lua_type":"string"},{"name":"stopFadeTimeOverride","desc":"","lua_type":"number?\\n"}],"returns":[],"function_type":"static","tags":["Animations"],"source":{"line":1166,"path":"src/init.luau"}},{"name":"StopAnimationInterrupt","desc":"Stops a registered animation using its interrupt stop fade time.\\n\\nUses `InterruptStopFadeTime` from the registered settings when present,\\notherwise stops immediately.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to stop","lua_type":"string"}],"returns":[],"function_type":"static","tags":["Animations"],"source":{"line":1183,"path":"src/init.luau"}},{"name":"IsAnimationPlaying","desc":"Returns whether a registered animation is currently playing.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to check","lua_type":"string"}],"returns":[{"desc":"True if the animation is playing","lua_type":"boolean"}],"function_type":"static","tags":["Animations"],"source":{"line":1194,"path":"src/init.luau"}},{"name":"IsAnimationFinished","desc":"Returns whether a non-looped animation has finished playing.\\n\\nLooped animations always return false.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"animationName","desc":"The animation to check","lua_type":"string"}],"returns":[{"desc":"True if the animation has finished","lua_type":"boolean"}],"function_type":"static","tags":["Animations"],"source":{"line":1207,"path":"src/init.luau"}},{"name":"IsCharacterTracked","desc":"Returns whether the animation system is tracking a character\'s root part.\\n\\nUse before `SetProcessingRootPart` from event-driven code: a root part the\\nsystem does not know yet (for example during the spawn frame) would\\notherwise leave no processing character set, and play calls would fall back\\nto the global pre-character path.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"rootPart","desc":"The character root part to check","lua_type":"BasePart"}],"returns":[{"desc":"True if animations can target this character","lua_type":"boolean"}],"function_type":"static","tags":["Animations"],"source":{"line":1223,"path":"src/init.luau"}},{"name":"SetProcessingRootPart","desc":"Sets the root part used by animation query and playback methods.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"rootPart","desc":"The character root part to target","lua_type":"BasePart?"}],"returns":[],"function_type":"static","tags":["Animations"],"source":{"line":1233,"path":"src/init.luau"}},{"name":"GetLoadedTrackLength","desc":"Returns the loaded track length for a registered animation on a character.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"rootPart","desc":"The character root part","lua_type":"BasePart"},{"name":"animationName","desc":"The registered animation name","lua_type":"string"}],"returns":[{"desc":"Track length in seconds, if loaded","lua_type":"number?"}],"function_type":"static","tags":["Animations"],"source":{"line":1245,"path":"src/init.luau"}},{"name":"WriteFlatLookDirection","desc":"Stores a flat look direction on a root part for replication.\\n\\nThe toolkit reads this at the end of each simulation step to orient the\\ncharacter. The Y component should usually be zero.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"rootPart","desc":"The character root part","lua_type":"BasePart"},{"name":"flatLookDirection","desc":"The horizontal look direction in world space","lua_type":"Vector3"}],"returns":[],"function_type":"static","tags":["Utility"],"source":{"line":1263,"path":"src/init.luau"}},{"name":"ReadFlatLookDirection","desc":"Reads the flat look direction stored on a root part.\\n\\nReturns `Vector3.new(0, 0, -1)` if no direction has been stored.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"rootPart","desc":"The character root part","lua_type":"BasePart"}],"returns":[{"desc":"The stored flat look direction","lua_type":"Vector3"}],"function_type":"static","tags":["Utility"],"source":{"line":1280,"path":"src/init.luau"}},{"name":"QuantizeFlatDirection","desc":"Rounds a flat direction to a fixed yaw step for stable network replication.\\n\\nYaw is quantized to 0.25 degree steps. Useful before calling\\n`WriteFlatLookDirection`.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"flatDirection","desc":"The direction to quantize","lua_type":"Vector3"}],"returns":[{"desc":"The quantized direction on the horizontal plane","lua_type":"Vector3"}],"function_type":"static","tags":["Utility"],"source":{"line":1294,"path":"src/init.luau"}},{"name":"GetRootStandHeight","desc":"Returns the expected distance from the character\'s root part center to the\\nground, derived from the humanoid rig (hip height, root size, and leg size\\nfor R6 rigs).\\n\\nUseful for modules that manage vertical placement against `GroundHeight`.\\nReturns nil when the state has no character.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"state","desc":"The movement state to measure","lua_type":"ServerAuthToolkitTypes.MovementState"}],"returns":[{"desc":"Root center height above the ground when standing","lua_type":"number?"}],"function_type":"static","tags":["Utility"],"source":{"line":1310,"path":"src/init.luau"}},{"name":"GetVerticalSpeedExcess","desc":"Returns vertical speed beyond what following the given ground plane accounts\\nfor. Riding a ramp keeps this near zero, while jump or knockback velocity\\npushes it past `GetGroundLeaveVerticalSpeed`.\\n\\nThis is the same math ground detection uses for its leave gate, so custom\\nmodules (launches, snaps, landing checks) stay consistent with it.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"velocity","desc":"The velocity to measure","lua_type":"Vector3"},{"name":"groundNormal","desc":"The ground plane normal the character moves along","lua_type":"Vector3"}],"returns":[{"desc":"Vertical speed in excess of plane-following movement","lua_type":"number"}],"function_type":"static","tags":["Utility"],"source":{"line":1330,"path":"src/init.luau"}},{"name":"ConfigureGroundDetection","desc":"Overrides ground detection tuning (step height, landing gap, leave speed,\\nwalkable slope limit). Omitted fields keep their defaults.\\n\\nCall identically on the server and the client, before or right after\\n`Start`; the values feed the predicted simulation, so a mismatch makes the\\nclient diverge from the server.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"},{"name":"config","desc":"Fields to override","lua_type":"ServerAuthToolkitTypes.GroundDetectionConfig"}],"returns":[],"function_type":"static","tags":["Register"],"source":{"line":1349,"path":"src/init.luau"}},{"name":"GetMaxStepHeight","desc":"Returns the maximum ledge height ground detection treats as a walkable step.\\n\\nGrounded characters stay grounded across ledges up to this height, so\\nmodules that snap or glide the character vertically should use the same\\nlimit.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[{"desc":"Maximum step height in studs","lua_type":"number"}],"function_type":"static","tags":["Utility"],"source":{"line":1366,"path":"src/init.luau"}},{"name":"GetGroundLeaveVerticalSpeed","desc":"Returns the vertical speed excess above which the character leaves the\\nground (see `GetVerticalSpeedExcess`).","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[{"desc":"Ground leave threshold in studs per second","lua_type":"number"}],"function_type":"static","tags":["Utility"],"source":{"line":1377,"path":"src/init.luau"}},{"name":"GetMinWalkableNormalY","desc":"Returns the minimum surface normal Y ground detection treats as walkable.\\nSurfaces below it are walls; modules that clip velocity against walls should\\nuse the same boundary.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[{"desc":"Minimum walkable normal Y","lua_type":"number"}],"function_type":"static","tags":["Utility"],"source":{"line":1389,"path":"src/init.luau"}},{"name":"Start","desc":"Starts movement simulation, player lifecycle handling, and the animation helper.\\n\\nCall once on the server and once on the client after registering modules.\\nSafe to call multiple times; later calls do nothing.","params":[{"name":"self","desc":"","lua_type":"ServerAuthToolkit"}],"returns":[],"function_type":"static","tags":["Register"],"source":{"line":1401,"path":"src/init.luau"}}],"properties":[],"types":[{"name":"MovementState","desc":"Per-player movement state updated each simulation step. Built-in fields track\\nthe character and ground info; modules add custom fields through `NeededStates`.","lua_type":"{ Character: Model?, Humanoid: Humanoid?, RootPart: BasePart?, CameraLookVector: Vector3?, OnGround: boolean?, GroundNormal: Vector3?, GroundHeight: number?, [string]: any }","tags":["General"],"source":{"line":15,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"BindingProps","desc":"Optional input binding settings for an action. Keys map to Roblox\\nInputBinding properties such as key codes, modifiers, and scale values.","lua_type":"{ Backward: Enum.KeyCode?, ClampMagnitudeToOne: boolean?, Down: Enum.KeyCode?, Forward: Enum.KeyCode?, KeyCode: Enum.KeyCode?, Left: Enum.KeyCode?, PointerIndex: number?, PressedThreshold: number?, PrimaryModifier: Enum.KeyCode?, ReleasedThreshold: number?, ResponseCurve: number?, Right: Enum.KeyCode?, Scale: number?, SecondaryModifier: Enum.KeyCode?, UIButton: Enum.UserInputType?, Up: Enum.KeyCode?, Vector2Scale: Vector2?, Vector3Scale: Vector3? }","tags":["Input Action System"],"source":{"line":42,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"ActionDefinition","desc":"Describes one input action in a movement module. `ApplyInput` writes the\\naction state into the player\'s movement state each simulation step.","lua_type":"{ Name: string, Type: Enum.InputActionType, Bindings: { [string]: BindingProps }, ApplyInput: (state: MovementState, inputState: any) -> () }","tags":["Input Action System"],"source":{"line":71,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"MovementModuleDefinition","desc":"Describes a movement module: input actions, default state, per-frame logic, and\\noptional Roblox actions to disable. Lower `Priority` runs first.\\n\\n`NonReplicatedStates` lists NeededStates fields that must NOT replicate as\\nattributes: fields re-derived every step (for example written by `ApplyInput`\\nfrom the input actions) waste the per-instance attribute payload budget and\\nneed no rollback restore. Like NeededStates, the list must be identical on\\nthe server and the client.","lua_type":"{ Name: string, Priority: number?, Actions: { ActionDefinition }, NeededStates: NeededStatesDefaults, NonReplicatedStates: { string }?, Process: (state: MovementState, deltaTime: number) -> (), Disable: { string }? }","tags":["General"],"source":{"line":92,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"GroundDetectionConfig","desc":"Optional tuning for ground detection. Omitted fields keep their defaults.\\nApply the same configuration on the server and the client, before or right\\nafter `Start`, or grounded state diverges between prediction and authority.","lua_type":"{ MaxStepHeight: number?, LandingGap: number?, GroundLeaveVerticalSpeed: number?, MinWalkableNormalY: number? }","tags":["General"],"source":{"line":111,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"PreCameraSimulationEntry","desc":"Internal entry for a registered pre-camera simulation callback.","lua_type":"{ name: string, callback: PreCameraSimulationCallback }","tags":["Callbacks"],"source":{"line":134,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"PostCameraVisualEntry","desc":"Internal entry for a registered post-camera visual callback.","lua_type":"{ name: string, callback: PostCameraVisualCallback, priority: number }","tags":["Callbacks"],"source":{"line":146,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"AnimationSettings","desc":"Playback settings for a registered animation. Only `Animation` is required;\\nomitted fields default to Speed 1, Weight 1, FadeTime 0.1, StopFadeTime 0.1,\\nLooped false, and Priority Action.","lua_type":"{ Animation: Animation, Speed: number?, Weight: number?, FadeTime: number?, StopFadeTime: number?, InterruptStopFadeTime: number?, Looped: boolean?, Priority: Enum.AnimationPriority? }","tags":["General"],"source":{"line":161,"path":"src/ServerAuthToolkitTypes.luau"}},{"name":"MovementState","desc":"Per-player movement state updated each simulation step. Built-in fields track\\nthe character and ground info; modules add custom fields through `NeededStates`.","lua_type":"{ Character: Model?, Humanoid: Humanoid?, RootPart: BasePart?, CameraLookVector: Vector3?, OnGround: boolean?, GroundNormal: Vector3?, GroundHeight: number?, [string]: any }","tags":["General"],"source":{"line":15,"path":"src/MovementStateBuilder.luau"}},{"name":"BindingProps","desc":"Optional input binding settings for an action. Keys map to Roblox\\nInputBinding properties such as key codes, modifiers, and scale values.","lua_type":"{ Backward: Enum.KeyCode?, ClampMagnitudeToOne: boolean?, Down: Enum.KeyCode?, Forward: Enum.KeyCode?, KeyCode: Enum.KeyCode?, Left: Enum.KeyCode?, PointerIndex: number?, PressedThreshold: number?, PrimaryModifier: Enum.KeyCode?, ReleasedThreshold: number?, ResponseCurve: number?, Right: Enum.KeyCode?, Scale: number?, SecondaryModifier: Enum.KeyCode?, UIButton: Enum.UserInputType?, Up: Enum.KeyCode?, Vector2Scale: Vector2?, Vector3Scale: Vector3? }","tags":["Input Action System"],"source":{"line":42,"path":"src/MovementStateBuilder.luau"}},{"name":"ActionDefinition","desc":"Describes one input action in a movement module. `ApplyInput` writes the\\naction state into the player\'s movement state each simulation step.","lua_type":"{ Name: string, Type: Enum.InputActionType, Bindings: { [string]: BindingProps }, ApplyInput: (state: MovementState, inputState: any) -> () }","tags":["Input Action System"],"source":{"line":71,"path":"src/MovementStateBuilder.luau"}},{"name":"MovementModuleDefinition","desc":"Describes a movement module: input actions, default state, per-frame logic, and\\noptional Roblox actions to disable. Lower `Priority` runs first.\\n\\n`NonReplicatedStates` lists NeededStates fields that must NOT replicate as\\nattributes: fields re-derived every step (for example written by `ApplyInput`\\nfrom the input actions) waste the per-instance attribute payload budget and\\nneed no rollback restore. Like NeededStates, the list must be identical on\\nthe server and the client.","lua_type":"{ Name: string, Priority: number?, Actions: { ActionDefinition }, NeededStates: NeededStatesDefaults, NonReplicatedStates: { string }?, Process: (state: MovementState, deltaTime: number) -> (), Disable: { string }? }","tags":["General"],"source":{"line":92,"path":"src/MovementStateBuilder.luau"}},{"name":"GroundDetectionConfig","desc":"Optional tuning for ground detection. Omitted fields keep their defaults.\\nApply the same configuration on the server and the client, before or right\\nafter `Start`, or grounded state diverges between prediction and authority.","lua_type":"{ MaxStepHeight: number?, LandingGap: number?, GroundLeaveVerticalSpeed: number?, MinWalkableNormalY: number? }","tags":["General"],"source":{"line":111,"path":"src/MovementStateBuilder.luau"}},{"name":"PreCameraSimulationEntry","desc":"Internal entry for a registered pre-camera simulation callback.","lua_type":"{ name: string, callback: PreCameraSimulationCallback }","tags":["Callbacks"],"source":{"line":134,"path":"src/MovementStateBuilder.luau"}},{"name":"PostCameraVisualEntry","desc":"Internal entry for a registered post-camera visual callback.","lua_type":"{ name: string, callback: PostCameraVisualCallback, priority: number }","tags":["Callbacks"],"source":{"line":146,"path":"src/MovementStateBuilder.luau"}},{"name":"AnimationSettings","desc":"Playback settings for a registered animation. Only `Animation` is required;\\nomitted fields default to Speed 1, Weight 1, FadeTime 0.1, StopFadeTime 0.1,\\nLooped false, and Priority Action.","lua_type":"{ Animation: Animation, Speed: number?, Weight: number?, FadeTime: number?, StopFadeTime: number?, InterruptStopFadeTime: number?, Looped: boolean?, Priority: Enum.AnimationPriority? }","tags":["General"],"source":{"line":161,"path":"src/MovementStateBuilder.luau"}}],"name":"ServerAuthToolkit","desc":"Server-authoritative movement toolkit for Roblox Input Actions and client\\nprediction.\\n\\nRegister movement modules and animations, then call `Start` on both the server\\nand client. Modules run each simulation step in priority order and replicate\\nstate through root-part attributes.","source":{"line":11,"path":"src/init.luau"}}')}}]);